<script setup lang="ts">
import {ref} from "vue";import {open} from "@tauri-apps/plugin-dialog";import {invoke} from "@tauri-apps/api/core";
const emit=defineEmits<{send:[body:string];sendImage:[path:string]}>();const draft=ref("");const isSendingImage=ref(false);
function submitMessage(){const body=draft.value.trim();if(!body)return;emit("send",body);draft.value=""}
async function selectImage(){if(isSendingImage.value)return;const file=await open({multiple:false,filters:[{name:"Изображение",extensions:["png","jpg","jpeg","webp","gif"]}]});if(!file||Array.isArray(file))return;try{isSendingImage.value=true;const savedPath=await invoke<string>("save_attachment",{source:file});emit("sendImage",savedPath)}finally{isSendingImage.value=false}}
</script>
<template><form class="composer" @submit.prevent="submitMessage"><button type="button" class="image-button" :disabled="isSendingImage" @click="selectImage">{{isSendingImage?'⏳':'📷'}}</button><input v-model="draft" type="text" placeholder="Напишите сообщение…" autocomplete="off"/><button type="submit">Отправить</button></form></template>
<style scoped>.composer{display:flex;gap:10px;padding:15px 20px;border-top:1px solid var(--border);background:var(--panel);flex-shrink:0}.composer input{flex:1;min-width:0;padding:11px 13px;border:1px solid var(--border);border-radius:8px;outline:none;color:var(--text);background:var(--input);font:inherit}.composer input:focus{border-color:#4f7fea}.composer button{padding:0 18px;border:none;border-radius:8px;cursor:pointer;color:white;background:#386be0;font:inherit;font-weight:600}.composer button:disabled{opacity:.6;cursor:wait}.image-button{width:42px;padding:0!important;font-size:18px!important;background:var(--input)!important;border:1px solid var(--border)!important;color:var(--text)!important}.image-button:hover:not(:disabled){background:var(--hover)!important}</style>
